(function(root){
  'use strict';
  const paragraph=(number,summary,technique,meaning,structure)=>({number,summary,technique,meaning,structure});
  root.SelfStudyAnalysis={
    'dse2024-fansheng':[
      paragraph(1,'想像百年前的農人走投無路，長途跋涉後看見綠色河谷，終於痛哭。','以「我常常想」引入想像；茫茫沙漠與綠色河谷形成反差，突出境遇的突然轉折。','痛哭是長期困頓後情感的釋放。河谷帶來生存的可能，但本段沒有保證未來必然美好。','從前人的拓荒經驗開篇，建立流浪、困苦與尋找生機的線索，末段再回到這個人。'),
      paragraph(2,'農人一直保留種子，運用簡陋工具勘測地勢，墾荒開渠。','用帶種、勘測、墾荒、開渠等行動描寫人物；「唯一不曾放棄」突出種子的分量。','種子承載求生與延續生命的希望；工具簡陋仍努力開墾，見出前人的韌性。','承接抵達河谷，展開開墾過程；種子與後文一家人的播種、留種互相照應。'),
      paragraph(3,'開渠灌溉令不知危險的魚湧入農田，擱淺死亡，魚屍在陽光下閃亮。','以「無憂無慮」描寫魚的物性；單薄秧苗、寂靜天地與閃亮魚屍並置，「繁盛」含反義寄意。','看似閃耀的繁盛實為生命枯萎；人類開墾已改變魚的生境，生機與死亡形成矛盾景象。','由農人的求生轉到開墾對魚群的影響，開始河谷生態變遷的敍述，亦扣連篇名。'),
      paragraph(4,'冬天人們以無餌無鉤的紅繩捕魚，魚被捉後仍不肯鬆口，憤怒而迷惑。','細寫魚的牙齒與緊咬動作，並賦予牠們憤怒、迷惑的感受；牙齒的描寫本身沒有構成比喻。','魚仍按原有習性生活，卻未理解環境已變；牠們的迷惑顯示人類介入打破了原來的世界。','續寫人與魚的關係，以「世界改變了」收束，與下一段的相同句子呼應。'),
      paragraph(5,'春天魚苗大量繁殖，人們捕撈幼魚餵牲畜，牲畜以至肉湯都帶魚腥氣。','以珠寶明喻魚苗的璀璨與繁多；由捕魚寫到牲畜和肉湯，呈現行為的連鎖影響。','大量耗用幼魚以換取眼前利益，損害魚群後續繁衍；蓬勃生命正被人類利用。','接續捕魚歷史，再以「世界改變了」作結，為魚群減少、河流被截的後果鋪墊。'),
      paragraph(6,'人口與耕地擴張，河流被截引往荒野，下游湖泊萎縮變鹹，魚最終消失。','以魚少人多作對照；吸吮乳汁與鮮血的比喻、對比，突出魚群生境由滋養轉向殘酷。','開墾的規模擴大，卻未帶來整片土地的真正繁盛，反而令水源及生命受損；魚群艱苦求生終至消失。','收束百年前開始的生態變遷，以「再也沒有魚了」形成沉重停頓，準備轉入一家人的經歷。'),
      paragraph(7,'多年後一家人來到新的耕地；道路、水渠都是新的，河卻衰老，重回的魚深藏而彼此疏離。','反覆「彷彿」及新、舊對照；將河寫成老去，並以魚的距離與隱藏位置表現內心感受。','表面的新開始掩蓋既有傷害。魚由無憂無慮變得恐懼、不安，顯示物性及自然關係已改變。','從前人轉到「我們」，銜接歷史與當下；與第3段魚群爭先湧入的情景形成對照。'),
      paragraph(8,'一家人因向日葵收益較高，在貧瘠土地上種植耗損地力的作物，作者認為自己與前人相似。','交代土壤、作物和收益之間的矛盾，再以「掠奪」直接作自我反省。','求生壓力令人在生態代價與收入之間選擇眼前收益。批評包含作者自己，不只是責備前人。','將兩代開墾者連在一起，點出困境的重複，並引出全家種向日葵的具體經歷。'),
      paragraph(9,'第一年播種全家動員，母親把外婆、動物、花草等幾乎半個家都搬到地邊。','逐項列舉同行的人、動物與花草，呈現搬家的規模和生活氣息。','種植牽動整個家庭及依附其中的生命，讓下文的辛勞與憂慮有具體承受者。','由概括種植原因轉入個人回憶，為夜間處理種子和外婆不願離家作交代。'),
      paragraph(10,'一家人連夜把種子拌上紅色農藥；作者想像種子列隊及鼠類面對它們的饑餓與畏懼。','以軍團、點兵大王、首長、守護神等比喻寫種子與勞動者；由實際拌種轉入地底的想像。','紅色種子既承載生存希望，也帶着威脅與不安；人的保護措施與鼠類的處境彼此牽連。','引入紅色與手電筒光芒，接下段不同生命的情緒匯聚；形成實景與想像交錯的敍述。'),
      paragraph(11,'家人的憂慮、痛苦和疲憊融入紅色；作者想像前人、魚群向微弱光芒聚攏，並感到希望極其脆弱。','紅色、金色、光與黑暗有象徵寄意；反覆「滲入」「彷彿」，把實景與想像交錯；絲線上端水的比喻突出危險和脆弱。','光可象徵希望、勇氣或決心，黑暗指向困頓；「撐開」見頑強，「小小」見希望微弱。流浪生命向光靠攏，表現困境中仍渴求生存與繁盛。','將家人、前人與消失的魚連成共同命運，集中呈現色彩與光的寄意，亦為種植遭遇及結尾回想前人作準備。'),
      paragraph(12,'首年種植缺水，種植戶激烈爭水，母親通宵守渠，最後在閘門旁露天過夜。','以平日客氣互助與灌溉時爭奪作對比，細寫母親查看水渠、露宿守水的行動。','資源不足使人際關係轉為競爭；母親為保護作物承受辛苦，也顯出耕種者求生的壓力。','從上一段的想像回到種植實況，具體說明黑暗般的困境，為旱災與病害的後果鋪墊。'),
      paragraph(13,'缺水和病蟲害令葵花大量死亡，母親憂心的不只是金錢，更是親手培育的生命消逝。','反覆「親眼看着」「一點點」，對照成長與枯萎的過程；由財產損失轉到生命感受。','耕種者與作物有感情聯繫；母親的痛苦超越盈虧，也與千百年耕種者的共同經驗相通。','把一家人的失收提升為長久的生命經驗，呼應前人的困苦，並準備下一段面對挫折的態度。'),
      paragraph(14,'大多數種植戶撤離，母親仍留種準備明年再種；外婆則記得葵花盛放的金光。','以撤離與堅持作對照；母親直率有力的說話刻劃性格，外婆的話突出金色花海。','母親顯出堅毅、不服輸或樂觀，金色寄寓生命繁盛與美好生活的期盼；曾經開花不等於困境已全部解決。','回應種植失敗後如何繼續生活，與前人保留種子照應；紅色與金色的線索將在末段再次出現。'),
      paragraph(15,'冬天作者帶着對紅色與金色的惦念走到河谷，想起魚和百年前的農人，既想安慰他，也想向他哭泣。','先寫真實雪景，再轉入前人冒雪而來的想像；母親與女兒兩種身分並置，並呼應開篇。','作者理解前人的苦難，又在共同命運中尋求安慰；安慰與哭泣同時表現憐惜、苦痛及生命在枯萎與求生之間的延續。','將歷史與當下、個人與眾生命重新連接，深化全文主旨；首尾呼應的作用要連到這份共同經驗來理解。')
    ],
    'dse2025-fiction':[
      paragraph(1,'提出小說中的人如何生活這個問題。','以設問開篇，先提出探討對象，讓讀者帶着問題閱讀。','文章關心的不限於故事情節，而是人物如何面對自身生活。','總領第2至4段關於小說、醒悟與現實生活的討論。'),
      paragraph(2,'小說人物會忽然醒悟；尼克厭倦上流社會而離開，默爾索由冷漠轉向感受幸福。','舉兩部小說的例子；尼克由相信到厭倦，默爾索由厭倦到相信，形成對比。','醒悟不只有一種方向，重點是重新理解原有生活，突破此前的認知。','回答開篇問題，提供下一段比較小說人物與現實之人的具體依據。'),
      paragraph(3,'作者期待小說人物質疑與醒悟的時刻，現實的人卻常逃避反省，以具體生活自我欺騙。','直接對比小說人物與現實的人；「表皮」「釘死」等形象用語突出偽裝與自我局限。','小說能促使讀者不再只沉溺生活細節，而重新盤問遭遇的意義；這是本文所說的小說價值。','由小說例子轉到現實處境，明確呈現第一部分的對比點與論意，並引出「陷阱」。'),
      paragraph(4,'生活瑣事的趣味可能令人沉淪，忘記某種生活本來需要改變。','先以「陷阱」比喻具體生活的束縛，再引王小波的話作說明。','細節本身可以有趣，但趣味可能遮蔽整體問題，令人停下反思和改變。','承接現實中自我欺騙的情況，收束第一部分關於醒悟的討論。'),
      paragraph(5,'引述一些人不再讀小說，認為小說虛假，偏好歷史、哲學與經濟書籍的說法。','重現常聽到的宣稱，並以「驕傲」提示作者對這種態度有所保留。','這種說法把小說的虛構性直接等同缺乏價值，是下文要回應的觀點。','提出待反駁的看法，轉入小說如何改變人觀看生活的第二部分。'),
      paragraph(6,'作者反駁小說虛假之說，以科羅的畫作說明藝術提供新目光，小說亦使生活更真實。','引用王爾德的俏皮話，以繪畫與小說的共同作用作類比，解釋「目光」。','藝術不是把自然變成畫，而是使觀者看見此前忽略的特點；小說同樣能改變理解生活的方式。','正面提出第二部分的中心觀點，再以卡夫卡的小說引向具體說明。'),
      paragraph(7,'卡夫卡的故事寫人物陷入迷宮、變成甲蟲或無法申冤，呈現面對未知力量的孤獨無助。','列舉小說中的不同困境，將抽象的無助感化為可以想像的處境。','小說替難以說清的生命狀態提供形象與名稱，讓人辨認自己面對的困境。','承接「生活像卡夫卡的小說」，具體展示文學目光如何讓生活變得可理解。'),
      paragraph(8,'文學的作用是提供觀看世界的目光。','用兩個「不提供」與一個「只能提供」作集中表述，並以美容美髮的說法帶出幽默。','作者把重點放在觀看與理解能力，而非立即有用的勵志口號或外在修飾。','總結前面的小說例子，提煉核心概念，再由第9段解開「目光」的意思。'),
      paragraph(9,'不同專業以用途看土地，文學則連起其過去未來與細微景象，從戰場、芳草、白骨思索生命。','以同一塊土地對比不同觀看角度；細節描寫與數百年的時間跨度並置。','文學看見事物之間及生死、過去未來的聯繫，亦能產生歷史情懷與非功利的生命反思。','以具體情境說明「文學的目光」，把抽象概念落到可分析的內容，為末段擴展作準備。'),
      paragraph(10,'文學目光使人持續發現萬物的聯繫，並藉小說的時間安排重新感受過去、現在與未來。','用超能力及微弱電流作比喻，引用《百年孤獨》的開頭說明多個時間點的交疊。','文學能突破日常單一視角，讓人感受細微聯繫與時間交錯；「時間是幻覺」須放在文學觀看的語境理解。','總結文學目光的持久影響，回應全文關於小說價值的討論，將目光擴展到萬物與時間。')
    ],
    'dse2025-alley':[
      paragraph(1,'離開繁忙正路走進無名長巷，令人驚奇與迷惘，作者把這種路感連到人生。','以行走經驗起筆，用長巷的路感比喻人生的探索。','人生不全是清楚既定的道路，也包含意外、未知與方向感的動搖。','開篇點出巷子與人生的關係，奠定全文由景象推到領悟的方向。'),
      paragraph(2,'巷子以人的尺度展現細密生活，房屋、氣味與積水帶着親近而壓抑的感受。','以房屋低首斂眉、雨水委屈怨恨作擬人；熟識的狗與委屈心事作比喻，並結合嗅覺、視覺描寫。','巷子比高樓大路更貼近生活細節，但親密之中也有窄小、鬱悶與累積的心事。','由開篇的路感深入巷子內部，呈現尺度與感受，接着轉向城市巷子的行走困境。'),
      paragraph(3,'城市長巷道路窄小高低不平，走路令人不安、顛沛流離，產生沒有歸屬的感覺。','細寫路面的起伏與缺乏行人空間，再以離鄉背井作比喻。','不舒適的路面與行走經驗轉化為精神上的漂泊，顯示人在城市中未必能安頓自身。','開始集中寫城市巷子的壓迫感，為下一段車燈打擾與慌亂作準備。'),
      paragraph(4,'冬夜走長巷時，後車的燈光迫人頻頻回首讓路，令人驚慌無奈。','以趕考書生寫孤身趕路，以往事化成鬼魅比喻車燈帶來的威脅；連串動作呈現被打斷的行走。','人被車催逼、無法安心前進，路感也喚起難以擺脫的往事與內在恐懼。','延續城市巷子的困境，與後文鄉下少車、從容觀看形成具體對照。'),
      paragraph(5,'城郊巷子與山林相接，草木、青苔、小花包圍簡便的居所，人與房屋顯得短暫。','列舉自然侵入生活空間的細節，將人的短暫與周圍的永恆對照。','相對自然，人所建造的環境微小而有限，讓人看見自身生命的短促。','由城市移到城郊，擴大觀看尺度，提供末段人生領悟可連繫的文本依據。'),
      paragraph(6,'鄉下巷子狹窄而少車，走路較從容，彎曲的道路隨聚落形成，轉折像村落的百年興衰。','以「少了車，就多了從容」概括因果，並以道路的轉折比喻村落歷史。','行走不再受車催逼，人才有餘裕感受環境；路的變化亦承載長久的人事興衰。','轉入鄉下巷子，與城市經驗形成對照，銜接作者探訪朋友的具體回憶。'),
      paragraph(7,'朋友家前的長巷像延續多年的歷史，巷尾仍是菜圃、花木與平常生活的聲息。','借長恨歌、春秋大夢、黃粱等語彙與典故連起長巷和人世，穿插景物及聲音描寫。','相對巷子和歷史的延續，人世的夢想與起落短暫；平常生活仍在安靜地繼續。','具體寫出鄉下長巷的時間與生活層次，為午後靜觀的場景營造氛圍。'),
      paragraph(8,'作者和朋友午後坐在騎樓陽光下，把草莓與菱角放在地上。','以簡單動作、食物色彩和斜照陽光描寫日常片刻。','放慢腳步、親近生活，從被催逼的行走轉成安定的停留與觀看。','交代第9段觀察景物的位置與心境，由走巷子轉為坐看事物經過。'),
      paragraph(9,'雞、老人、昆蟲、貓影和念頭依次經過，沒有車輛打擾。','七行仍是同一原文段落；短句反覆「過」，排列生活中的微小動態，末句「沒有」形成轉折。','各種生命與念頭只是短暫經過，像人生中的過客；少了車的催逼，才能從容觀看並放下急迫與執着。','承接坐看巷子的場景，與第4段車輛打擾對照；節奏要結合從容心境判斷，不能只因短句便判為急速。'),
      paragraph(10,'作者感到時間在長巷中失去影子，坐看巷子彷彿看見人生。','把時間寫成在巷子中行走的事物，由具體景象轉入抽象感悟，照應開篇。','可以由前文理解人生的短暫與渺小，也可領會忘卻生活催逼、以從容心境感受人生；領悟須由景象支持。','點明巷子與人生的關係，收束全篇；不是只把看景換成一句泛泛的哲理。')
    ],
    'dse2026-voice':[
      paragraph(1,'旅遊開發中的藏女英珠以租馬謀生；遭雪暴時她照顧幼駒，唱歌安撫旅伴，令作者留下深刻記憶。','以經歷敍事，細寫羞澀低頭、卸物、裹衣與吟唱等言行；旅伴抱怨與歌聲帶來的安靜相映。','英珠生活艱辛、謀生不易，仍有善意與溫度。她的歌聲是真實人情的表現，而非只是一段悅耳聲音。','以具體歌聲開篇，建立「聲音」的意象，讓第2段能由一個人推到世上大多數人。'),
      paragraph(2,'普通人的聲音常被日常淹沒，卻陪伴人們，包含生活艱辛、平靜及堅持的信念。','以聲音、基調、主旋律等音樂語彙說明人生；將艱辛與祥和平靜並置。','「聲音」擴展為普通人的生活與信念。平凡人的執着和人情，也能構成生活的力量。','由英珠個案概括全文關注的人群與價值，為小說人物和藝人的故事提供共同主線。'),
      paragraph(3,'作者寫過一位叫英雄的平凡小說人物，他在時代變革中有膽識並屢次成功，後來個性與境遇衝突而走向悲劇。','以名字「英雄」與平凡人身分相連，敍述成功到悲劇的變化，並從人性角度理解欲望。','英雄可來自有溫度、有理想與膽識的普通人；世俗成功與人性弱點並存，不能只用完美或成敗來評價。','從真實旅行轉到小說人物，增加另一種人生聲音，並引向對人之常情的感受。'),
      paragraph(4,'作者認為令人持久難過的，不只是悲劇事件本身，更是其中的人之常情。','先區分悲劇與人情，再直接表述自己的閱讀和人生感受。','人情使平凡生命值得關注；悲傷不必來自戲劇化事件，也可來自普通人的真實處境。','承接小說人物的悲劇，又引出馬師傅這種較平常而令人惋惜的經歷。'),
      paragraph(5,'作者回憶有生氣的朝天宮市場及泥人藝人馬師傅，細寫他以耍貨維生、專注製作細貨的技藝。','列舉市場人物，配合肖像、動作與交談刻劃馬師傅；比較耍貨的批量製作與細貨的手工創作。','馬師傅既要謀生，也守住技藝與傳統戲曲的詮釋；他的專注和創造力，是作者珍惜的可貴價值。','以較詳篇幅具體建立藝人形象及舊城市的生氣，為下一段預想其凋落與惋惜提供原因。'),
      paragraph(6,'馬師傅等外來藝人承載城市殘存的性情，作者卻預想他必然黯淡離開。','以夕陽晚照比喻凋落，並將個人与城市的秉性相連。','時代、城市環境和生活需求的變化，使傳統藝人的立足空間減少；可貴技藝與人情面臨消逝，令人無奈惋惜。本段寫預想，不是證實死亡。','收束馬師傅的故事，將人物命運連到城市與時代的變化，深化前段的懷念。'),
      paragraph(7,'這些人物在回想中逐漸清晰，多年的快樂與痛苦如今像一波微瀾。','以水落石出和微瀾的形象寫回憶後的觀看，從人物故事轉向抒情。','時間使人看清人生的格局，也使強烈悲喜沉澱；平凡經驗在回想中仍留下分量。','匯合前面的不同人物，轉入作者對回憶、成長與真實人情的總結。'),
      paragraph(8,'作者願沿成長軌跡，以少年的眼睛重新看久違的人事，在不同情緒中感受真實與溫存。','以觀看與行走組織回憶，並列親近、憂傷、激蕩等感受，最後集中於真實與溫存。','作者珍惜普通人的真切人性；少年目光保留了親近與純淨，使回憶在惋惜之外仍帶來安慰。','交代全篇觀看人物的態度，為「邊緣的英雄」這個概括建立情感依據。'),
      paragraph(9,'作者稱這些平凡人物為行走於邊緣的英雄。','用簡短獨立段落作集中評價，將「邊緣」與「英雄」兩個概念並置。','邊緣指容易被忽略、艱辛謀生或信念不被理解的處境；英雄指他們仍有溫度、理想、膽識與生活信念。英珠的境況和言行可具體說明兩者。','凝練全文的人物評價，與第3段叫英雄的主角相連，再由末段把個人聲音合成民間。'),
      paragraph(10,'個別零落的聲音匯成和音，呈現時代的輪廓，其根本是民間。','引用音樂語句，再以聲響合成和音的比喻，將不同人生連成整體。','聲音涵括普通人的經歷、真實人情與信念。被忽略的生命共同構成時代，值得被聽見與珍視。','照應篇名及第2段對聲音的概括，總結英珠、小說人物、馬師傅等故事，把個人的真實提升到民間與時代。')
    ]
  };
})(typeof window!=='undefined'?window:globalThis);
